function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 10) return 'arr needs 1 to 10 values.';
  const seen = new Set();
  for (const v of arr) {
    if (!Number.isInteger(v) || v < 0 || v >= arr.length) return 'Each value must be between 0 and n - 1.';
    if (seen.has(v)) return 'arr must not repeat a value.';
    seen.add(v);
  }
  return null;
}

