function maxChunksToSorted(arr) {
  let chunks = 0;
  let maxSeen = -1;
  for (let i = 0; i < arr.length; i++) {
    maxSeen = Math.max(maxSeen, arr[i]);
    if (maxSeen === i) {
      chunks++;
    }
  }
  return chunks;
}

