function maxChunksToSorted(arr) {
  // Try every way to cut between neighbours and keep the valid cut with the most pieces.
  const n = arr.length;
  let best = 0;
  for (let mask = 0; mask < (1 << (n - 1)); mask++) {
    const glued = [];
    let piece = [arr[0]];
    let count = 1;
    for (let i = 1; i < n; i++) {
      if (mask & (1 << (i - 1))) {
        glued.push(...piece.sort((a, b) => a - b));
        piece = [];
        count++;
      }
      piece.push(arr[i]);
    }
    glued.push(...piece.sort((a, b) => a - b));
    if (glued.every((v, i) => v === i)) best = Math.max(best, count);
  }
  return best;
}

