function generate(rand, size) {
  const pick = (m) => Math.floor(rand() * m);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const n = size === 'large' ? 10 : 1 + pick(7);
  if (rand() < 0.5) return [shuffle(Array.from({ length: n }, (_, i) => i))];
  // Build the permutation from shuffled blocks of consecutive values so several chunks exist.
  const arr = [];
  let start = 0;
  while (start < n) {
    const length = Math.min(n - start, 1 + pick(3));
    arr.push(...shuffle(Array.from({ length }, (_, i) => start + i)));
    start += length;
  }
  return [arr];
}
